SELECT status, CASE WHEN account_type IN ('CREDIT', 'CHECKING') THEN 'tier_1' ELSE 'other' END account_type_group, COUNT(*) num_accounts, SUM(balance) total_balance, MIN(opened_date) min_opened_date FROM accounts WHERE balance >= 57000 OR MONTH(opened_date) IN (8, 9, 12) GROUP BY status, CASE WHEN account_type IN ('CREDIT', 'CHECKING') THEN 'tier_1' ELSE 'other' END ORDER BY min_opened_date DESC
